const topWindow = aras.getMostTopWindowWithAras(window);
const item = topWindow.item;
if (!item) {
	return {};
}

const itemTypeName = topWindow.itemTypeName;
const lockedBy = aras.getItemProperty(item, 'locked_by_id', '');
const lockFlg = aras.uiItemCanBeLockedByUser(
	item,
	topWindow.isRelationshipIT,
	topWindow['use_src_accessIT']
);
const unlockFlg = aras.isLockedByUser(item);
const purgeFlg =
	lockedBy === '' && !window.isFunctionDisabled(itemTypeName, 'Delete');
const revisionFlg = isVersionableIT && !aras.isTempEx(item);
const discussionFlg = topWindow.isSSVCEnabled && !aras.isNew(item);
const promoteFlg = lockFlg && !window.isFunctionDisabled(itemTypeName, 'Promote');

return {
	canDoRevision: revisionFlg,
	canPromote: promoteFlg,
	canPurge: purgeFlg,
	canUnlock: unlockFlg,
	discussionEnabled: discussionFlg
};
